{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "author": {
    "email": "danielnep.2011@gmail.com",
    "name": "Daniel Xavier"
  },
  "description": "Auditor UI/UX Horizon para repositórios e interfaces",
  "extensions": {
    "com.openai": {
      "apps": "./.app.json",
      "interface": {
        "brandColor": "#2876B9",
        "capabilities": [
          "Interactive",
          "Read",
          "Write"
        ],
        "category": "Developer Tools",
        "composerIcon": "./assets/tool-icon-small.png",
        "defaultPrompt": [
          "Antes de alterar codigo ou CSS, use $agente-editor e corrija na implementacao original: nao empilhe overrides, patches ou arquivos para anular codigo antigo; consolide e remova duplicatas, preservando funcionamento e validando regressoes."
        ],
        "developerName": "Daniel Xavier",
        "displayName": "Horizon UI Guardian",
        "logo": "./assets/tool-icon.png",
        "longDescription": "Auditor UI/UX Horizon para repositórios e interfaces. Inclui ciclo de melhoria continua com verificacao de hipoteses e regressao, preservando as funcionalidades e a autorizacao do usuario.",
        "shortDescription": "Auditor UI/UX Horizon para repositórios e interfaces"
      }
    }
  },
  "keywords": [
    "correcao-na-origem",
    "refatoracao",
    "sem-overrides"
  ],
  "name": "horizon-ui-guardian",
  "version": "0.1.13"
}

